25	    pub fn new(info: ImportInfo, groups: Option<&ImportGroups>) -> Self {
26	        Self {
27	            group: groups.map_or(0, |groups| groups.index(&((&info).into()))),
28	            source: info.source,
29	            has_no_attributes: info.has_no_attributes,
30	            kind: info.kind,
31	            slot_index: info.slot_index,
32	        }
33	    }
