46	pub enum ImportStatementKind {
47	    NamespaceType = 1 << 0,
48	    DefaultType = 1 << 1,
49	    NamedType = 1 << 2,
50	    Namespace = 1 << 3,
51	    DefaultNamespace = 1 << 4,
52	    Default = 1 << 5,
53	    DefaultNamed = 1 << 6,
54	    Named = 1 << 7,
55	}
56	impl ImportStatementKind {
57	    pub fn has_type_token(self) -> bool {
58	        (Self::DefaultType | Self::NamespaceType | Self::NamedType).contains(self)
59	    }
60	
61	    pub fn is_mergeable(self, kinds: enumflags2::BitFlags<Self>) -> bool {
62	        match self {
63	            Self::Namespace => kinds.contains(Self::Default),
64	            Self::Default => kinds.intersects(Self::Namespace | Self::Named),
65	            Self::DefaultNamed => kinds.contains(Self::Named),
66	            Self::Named => kinds.intersects(Self::DefaultNamed | Self::Named | Self::Default),
67	            Self::NamedType => kinds.contains(Self::NamedType),
68	            _ => false,
69	        }
70	    }
71	}
