36	pub fn are_import_specifiers_sorted(
37	    named_specifiers: &JsNamedImportSpecifiers,
38	    sort_order: SortOrder,
39	) -> Option<bool> {
40	    let comparator = get_comparator(sort_order);
41	
42	    is_separated_list_sorted_by(
43	        &named_specifiers.specifiers(),
44	        |node| {
45	            let AnyJsBinding::JsIdentifierBinding(name) = node.local_name()? else {
46	                return None;
47	            };
48	            Some(ComparableToken::new(
49	                name.name_token().ok()?.token_text_trimmed(),
50	            ))
51	        },
52	        comparator,
53	    )
54	    .ok()
55	}
