57	pub fn sort_import_specifiers(
58	    named_specifiers: JsNamedImportSpecifiers,
59	    sort_order: SortOrder,
60	) -> Option<JsNamedImportSpecifiers> {
61	    let comparator = get_comparator(sort_order);
62	    let new_list = sorted_separated_list_by(
63	        &named_specifiers.specifiers(),
64	        |node| {
65	            let AnyJsBinding::JsIdentifierBinding(name) = node.local_name()? else {
66	                return None;
67	            };
68	            Some(ComparableToken::new(
69	                name.name_token().ok()?.token_text_trimmed(),
70	            ))
71	        },
72	        || make::token(T![,]).with_trailing_trivia([(TriviaPieceKind::Whitespace, " ")]),
73	        comparator,
74	    )
75	    .ok()?;
76	    Some(named_specifiers.with_specifiers(new_list))
77	}
