79	pub fn merge_import_specifiers(
80	    named_specifiers1: JsNamedImportSpecifiers,
81	    named_specifiers2: &JsNamedImportSpecifiers,
82	    sort_order: SortOrder,
83	) -> Option<JsNamedImportSpecifiers> {
84	    let specifiers1 = named_specifiers1.specifiers();
85	    let specifiers2 = named_specifiers2.specifiers();
86	    let mut nodes = Vec::with_capacity(specifiers1.len() + specifiers2.len());
87	    let mut separators = Vec::with_capacity(specifiers1.len() + specifiers2.len());
88	    for AstSeparatedElement {
89	        node,
90	        trailing_separator,
91	    } in specifiers1.elements()
92	    {
93	        let separator = trailing_separator.ok()?;
94	        let mut node = node.ok()?;
95	        if separator.is_none() {
96	            node = node.trim_trailing_trivia()?;
97	        }
98	        let separator = separator.unwrap_or_else(|| {
99	            make::token(T![,]).with_trailing_trivia([(TriviaPieceKind::Whitespace, " ")])
100	        });
101	        nodes.push(node);
102	        separators.push(separator);
103	    }
104	    for AstSeparatedElement {
105	        node,
106	        trailing_separator,
107	    } in specifiers2.elements()
108	    {
109	        nodes.push(node.ok()?);
110	        if let Some(separator) = trailing_separator.ok()? {
111	            separators.push(separator);
112	        }
113	    }
114	    let new_list = make::js_named_import_specifier_list(nodes, separators);
115	    sort_import_specifiers(named_specifiers1.with_specifiers(new_list), sort_order)
116	}
